-- DocHUB seed: "Quality Highlight - Incoming" (generated by server/scripts/exportSeedSql.ts — do not edit by hand)
-- Inserted automatically at start-up (src/scripts/migrate.ts → applySeeds), once per database (table AppliedSeeds);
-- skipped when the file is already there (same file id, or a live file with one of the names below).
-- Folder: Quality Highlight Report / Data (existing folders are re-used). Pictures: database/seed/files → UPLOAD_DIR.
SET NOCOUNT ON;
IF EXISTS (SELECT 1 FROM Files WHERE file_id IN ('54d453cc-9f4c-4fee-a9c6-a8705dfad684'))
   OR EXISTS (SELECT 1 FROM Files WHERE is_deleted = 0 AND file_name IN (N'Quality Highlight - Incoming'))
BEGIN SELECT N'skipped (already there)' AS result; RETURN; END;

DECLARE @u UNIQUEIDENTIFIER = (SELECT TOP 1 u.user_id FROM Users u JOIN UserRoles ur ON ur.user_id = u.user_id JOIN Roles r ON r.role_id = ur.role_id
                               WHERE r.role_name = N'admin' AND u.is_active = 1 ORDER BY u.created_at);
IF @u IS NULL SET @u = (SELECT TOP 1 user_id FROM Users WHERE is_active = 1 ORDER BY created_at);
IF @u IS NULL BEGIN SELECT N'skipped (no user yet)' AS result; RETURN; END;

DECLARE @top UNIQUEIDENTIFIER = (SELECT TOP 1 folder_id FROM Folders WHERE is_deleted = 0 AND parent_id IS NULL AND folder_name = N'Quality Highlight Report' ORDER BY created_at);
IF @top IS NULL BEGIN SET @top = NEWID(); INSERT INTO Folders (folder_id, folder_name, parent_id, created_by) VALUES (@top, N'Quality Highlight Report', NULL, @u); END;
DECLARE @sub UNIQUEIDENTIFIER = (SELECT TOP 1 folder_id FROM Folders WHERE is_deleted = 0 AND parent_id = @top AND folder_name = N'Data' ORDER BY created_at);
IF @sub IS NULL BEGIN SET @sub = NEWID(); INSERT INTO Folders (folder_id, folder_name, parent_id, created_by) VALUES (@sub, N'Data', @top, @u); END;





